#!/usr/bin/env bash
# Rebuild the approved release from the preserved V1.0 project archive.
set -euo pipefail
repo=OnRail76/Escoria-Sideral
out=$(realpath -m "${2:-.}")
mkdir -p "$out"
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
if [[ $# -ge 1 && "$1" != '--download' ]]; then old=$(realpath "$1"); else
  gh release download v1.0 --repo "$repo" --pattern 'ESCORIA_SIDERAL_V1.0_PROYECTO_FINAL.zip' --dir "$work"
  old="$work/ESCORIA_SIDERAL_V1.0_PROYECTO_FINAL.zip"
fi
unzip -q "$old" -d "$work"
(cd "$work/ESCORIA_SIDERAL_V1.0" && sha256sum -c SHA256SUMS.txt --quiet)
mv "$work/ESCORIA_SIDERAL_V1.0" "$work/ESCORIA_SIDERAL_V1.0.1"
cd "$work/ESCORIA_SIDERAL_V1.0.1"
base64 -d > "$work/delta.zip" <<'ESCORIA_PAYLOAD'
