ESCORIA_PAYLOAD
unzip -oq "$work/delta.zip"
python3 FUENTES/actualizar_atlas.py DOCUMENTACION/ESCORIA_SIDERAL_V1.0_ATLAS_MANUAL_MEMORIA.pdf DOCUMENTACION/ESCORIA_SIDERAL_V1.0.1_ATLAS_MANUAL_MEMORIA.pdf
rm -f JUEGO/ESCORIA_SIDERAL_V1.0.tap DOCUMENTACION/ESCORIA_SIDERAL_V1.0_ATLAS_MANUAL_MEMORIA.pdf FUENTES/ESCORIA_SIDERAL_ALFA_21_2.tap
(cd FUENTES && python3 build_release.py)
mkdir -p FUENTES/PRUEBAS_V1_0
for f in FUENTES/*results*.txt; do [[ ! -f "$f" ]] || mv "$f" FUENTES/PRUEBAS_V1_0/; done
# New source snapshots were generated from identical artwork; carry them from the original capture bank.
for f in captura_carga.png captura_enfermera_muerte_06.png captura_enfermera_muerte_25.png captura_enfermera_muerte_58.png captura_enfermera_muerte_88.png captura_enfermera_muerte_98.png captura_selector.png captura_suelo_v3.png; do cp "CAPTURAS/$f" FUENTES/; done
find . -type d -name __pycache__ -exec rm -rf {} +
find . -type f ! -name SHA256SUMS.txt -print0 | sort -z | xargs -0 sha256sum > SHA256SUMS.txt
sha256sum -c SHA256SUMS.txt --quiet
cp JUEGO/ESCORIA_SIDERAL_V1.0.1.tap "$out/"
cp DOCUMENTACION/ESCORIA_SIDERAL_V1.0.1_ATLAS_MANUAL_MEMORIA.pdf "$out/"
cd "$work"
zip -q -r "$out/ESCORIA_SIDERAL_V1.0.1_PROYECTO_FINAL.zip" ESCORIA_SIDERAL_V1.0.1
